using namespace cg3::cgal::internal;

// Convert Polygon2d to CGAL Polygon_2
Polygon_2 cgalP1, cgalP2;
for (const auto& p : P1.vectorPoints()) {
    cgalP1.push_back(Point_2(p.x(), p.y()));
}
for (const auto& p : P2.vectorPoints()) {
    cgalP2.push_back(Point_2(p.x(), p.y()));
}

// Compute union
Pwh_list_2 result;
CGAL::join(cgalP1, cgalP2, std::back_inserter(result));

// Convert back to PolygonWithHoles2d
std::vector<PolygonWithHoles2d> output;
for (const auto& pwh : result) {
    PolygonWithHoles2d polyWithHoles;

    // Convert outer boundary
    std::vector<Point2d> outer;
    for (auto it = pwh.outer_boundary().vertices_begin(); it != pwh.outer_boundary().vertices_end(); ++it) {
        double x, y;
        getCoordinates(*it, x, y);
        outer.emplace_back(x, y);
    }
    polyWithHoles.outer = outer;

    // Convert holes
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<Point2d> hole;
        for (auto it = hit->vertices_begin(); it != hit->vertices_end(); ++it) {
            double x, y;
            getCoordinates(*it, x, y);
            hole.emplace_back(x, y);
        }
        polyWithHoles.holes.push_back(hole);
    }

    output.push_back(polyWithHoles);
}

return output;

